  function start() {
    var loader = document.getElementById('loader');
    if (!loader) return;

    if (typeof gsap === 'undefined') {
      loader.hidden = true;
      loader.style.display = 'none';
      return;
    }

    var NS = 'http://www.w3.org/2000/svg';
    var svg = document.getElementById('loaderSails');
    if (!svg) {
      loader.hidden = true;
      loader.style.display = 'none';
      return;
    }

    svg.innerHTML = '';
    var paths = sails.map(function (s) {
      var p = document.createElementNS(NS, 'path');
      p.setAttribute('d', s.d);
      p.setAttribute('fill', s.color);
      p.setAttribute('stroke', s.color);
      svg.appendChild(p);
      var len = p.getTotalLength();
      p.style.strokeDasharray = len;
      p.style.strokeDashoffset = len;
      return p;
    });

    document.documentElement.style.overflow = 'hidden';

    var finished = false;
    function finish() {
      if (finished) return;
      finished = true;
      loader.classList.add('is-out');
      gsap.to(loader, {
        opacity: 0,
        duration: 0.35,
        ease: 'power2.out',
        onComplete: function () {
          loader.hidden = true;
          loader.style.display = 'none';
        }
      });
      document.documentElement.style.overflow = '';
      removeSkip();
    }

    function peel() {
      paths.forEach(function (p, i) {
        var bb = p.getBBox();
        gsap.to(p, {
          x: 60 + i * 26,
          y: -70 - i * 18,
          rotation: 8 + i * 3,
          scale: 1.25,
          opacity: 0,
          svgOrigin: bb.x + ' ' + (bb.y + bb.height),
          duration: 1.1,
          delay: (3 - i) * 0.07,
          ease: 'power3.in'
        });
      });
      gsap.to('.loader-word', { opacity: 0, y: 10, duration: 0.4 });
      gsap.to(loader, { backgroundColor: 'rgba(255,255,255,0)', duration: 0.9, delay: 0.45, ease: 'power2.inOut' });
      tl.pause();
      gsap.delayedCall(1.45, function () { tl.resume(); });
    }

    var tl = gsap.timeline({ onComplete: finish, paused: true });
    // Start only after two settled frames so a slow first render cannot swallow the intro
    requestAnimationFrame(function () {
      requestAnimationFrame(function () {
        tl.play(0);
      });
    });

    tl.to(paths, { strokeDashoffset: 0, duration: 0.9, stagger: 0.12, ease: 'power2.inOut' })
      .to(paths, { fillOpacity: 1, duration: 0.45, stagger: 0.08 }, '-=0.35')
      .to('.loader-word', { opacity: 1, duration: 0.5 }, '-=0.3')
      .add(peel, '+=0.35');

    function skip() {
      if (!finished) {
        tl.progress(1);
        finish();
      }
    }

    var skipEvents = ['keydown', 'pointerdown', 'wheel', 'touchstart'];
    function removeSkip() {
      skipEvents.forEach(function (e) {
        window.removeEventListener(e, skip);
      });
    }
    skipEvents.forEach(function (e) {
      window.addEventListener(e, skip, { passive: true });
    });

    // Fallback safety timeout
    setTimeout(function () {
      if (!finished) finish();
    }, 4500);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
